// The project number is the text in square brackets in the subject, e.g. "[2026-014] Delivery note".
const subject = $json.subject ?? '';
const match = subject.match(/\[([^\]]+)\]/);
const binary = $input.item.binary ?? {};

return {
  json: {
    projectNumber: match ? match[1].trim() : '',
    subject,
    sender: $json.from?.value?.[0]?.address ?? '',
    text: $json.text || subject,
    messageId: $json.messageId ?? '',
    attachmentFields: Object.keys(binary).join(', '),
  },
  binary,
};

// Find Project outputs only the projects it found, so pair each email with its project here.
const projects = $input.all().map((item) => item.json).filter((project) => project.id);

return $('Has Project Number?').all(0).map((email) => ({
  json: {
    ...email.json,
    projectId: projects.find((project) => project.customId === email.json.projectNumber)?.id ?? '',
  },
  binary: email.binary,
}));
